package service;
import model.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import java.math.BigDecimal;import java.nio.file.Path;import java.time.*;import java.util.List;import static org.junit.jupiter.api.Assertions.*;
class PassbookStatementTest {
 @TempDir Path temp;
 @Test void statementShowsSavedBalancesAndTransactionChronology(){var t1=new BankTransaction("t1","1234567890",TransactionType.DEPOSIT,new BigDecimal("50.00"),LocalDateTime.of(2026,1,2,10,0),new BigDecimal("150.00"),null);var t2=new BankTransaction("t2","1234567890",TransactionType.WITHDRAWAL,new BigDecimal("20.00"),LocalDateTime.of(2026,1,3,10,0),new BigDecimal("130.00"),null);var report=new PassbookStatement("1234567890",LocalDate.of(2026,1,2),LocalDate.of(2026,1,3),new BigDecimal("100.00"),new BigDecimal("130.00"),List.of(t1,t2));String text=report.render();assertTrue(text.contains("Opening: ₹100.00"));assertTrue(text.contains("Closing: ₹130.00"));assertTrue(text.indexOf("t1")<text.indexOf("t2"));}
 @Test void pdfExportCreatesReadablePages()throws Exception{var report=new PassbookStatement("1234567890",LocalDate.of(2026,1,1),LocalDate.of(2026,1,1),BigDecimal.ZERO,BigDecimal.ZERO,List.of());Path pdf=temp.resolve("statement.pdf");new PassbookService(null).exportPdf(report,pdf);try(var document=org.apache.pdfbox.pdmodel.PDDocument.load(pdf.toFile())){assertEquals(1,document.getNumberOfPages());}}
 @Test void signedBalanceChangeDependsOnTransactionType(){var in=new BankTransaction("1","1234567890",TransactionType.TRANSFER_IN,new BigDecimal("9.00"),LocalDateTime.now(),new BigDecimal("9.00"),"ref");var out=new BankTransaction("2","1234567890",TransactionType.TRANSFER_OUT,new BigDecimal("4.00"),LocalDateTime.now(),new BigDecimal("5.00"),"ref");assertEquals(new BigDecimal("9.00"),PassbookStatement.signedChange(in));assertEquals(new BigDecimal("-4.00"),PassbookStatement.signedChange(out));}
}
